-- The project tracker template, as Postgres tables. Made by baseToSql (@svgrid/enterprise/base);
-- the svgrid: comments keep what SQL has no type for, so baseFromDatabase opens it as the same base.

create table "tasks" (
  "id" text primary key default gen_random_uuid()::text,
  "task" text,
  "no" double precision,
  "status" text,
  "tags" text[],
  "files" jsonb,
  "assignee" text,
  "owner" text,
  "start" date,
  "due" date,
  "estimate" double precision,
  "progress" double precision,
  "milestone_id" text,
  "priority" double precision,
  "budget" double precision,
  "spec" text,
  "done" boolean
);
create table "milestones" (
  "id" text primary key default gen_random_uuid()::text,
  "name" text,
  "date" date
);
create table "tasks_depends_on" (
  "id" serial primary key,
  "task_id" text not null,
  "depends_on_id" text not null
);

comment on column "tasks"."task" is 'svgrid:{"field":"task","header":"Task","width":230,"fieldType":"text"}';
comment on column "tasks"."no" is 'svgrid:{"field":"no","header":"No","width":92,"fieldType":"autoNumber"}';
comment on column "tasks"."status" is 'svgrid:{"field":"status","header":"Status","width":130,"fieldType":"singleSelect","fieldProps":{"options":[{"value":"Todo","color":"#64748b"},{"value":"In progress","color":"#2563eb"},{"value":"Blocked","color":"#dc2626"},{"value":"Done","color":"#16a34a"}]}}';
comment on column "tasks"."tags" is 'svgrid:{"field":"tags","header":"Tags","width":190,"fieldType":"multiSelect","fieldProps":{"options":[{"value":"Design","color":"#9333ea"},{"value":"Backend","color":"#0891b2"},{"value":"Frontend","color":"#ea580c"},{"value":"Docs","color":"#65a30d"}]}}';
comment on column "tasks"."files" is 'svgrid:{"field":"files","header":"Files","width":180,"fieldType":"attachment","fieldProps":{"maxFiles":10}}';
comment on column "tasks"."assignee" is 'svgrid:{"field":"assignee","header":"Assignee","width":160,"fieldType":"user"}';
comment on column "tasks"."owner" is 'svgrid:{"field":"owner","header":"Owner","width":170,"fieldType":"email"}';
comment on column "tasks"."start" is 'svgrid:{"field":"start","header":"Start","width":180,"fieldType":"date","fieldProps":{"dateFormat":"friendly"}}';
comment on column "tasks"."due" is 'svgrid:{"field":"due","header":"Due","width":200,"fieldType":"date","fieldProps":{"dateFormat":"friendly"}}';
comment on column "tasks"."estimate" is 'svgrid:{"field":"estimate","header":"Estimate","width":100,"fieldType":"duration","fieldProps":{"durationFormat":"h:mm"}}';
comment on column "tasks"."progress" is 'svgrid:{"field":"progress","header":"Progress","width":150,"fieldType":"number","fieldProps":{"format":"percent","precision":0,"showBar":true,"summary":"avg"}}';
comment on column "tasks"."milestone_id" is 'svgrid:{"field":"milestone","header":"Milestone","width":130,"fieldType":"link","fieldProps":{"table":"milestones","multiple":false,"inverse":"tasks"}}';
comment on column "tasks"."priority" is 'svgrid:{"field":"priority","header":"Priority","width":120,"fieldType":"rating","fieldProps":{"max":5,"icon":"flag","color":"#f82b60"}}';
comment on column "tasks"."budget" is 'svgrid:{"field":"budget","header":"Budget","width":136,"description":"Approved spend for the task","fieldType":"number","fieldProps":{"format":"currency","symbol":"$","precision":0,"summary":"sum"}}';
comment on column "tasks"."spec" is 'svgrid:{"field":"spec","header":"Spec","width":200,"fieldType":"url"}';
comment on column "tasks"."done" is 'svgrid:{"field":"done","header":"Done","width":80,"fieldType":"checkbox","fieldProps":{"icon":"check","color":"#20c933"}}';
comment on table "tasks" is 'svgrid:{"v":1,"name":"Tasks","position":0,"primaryField":"task","order":["task","no","status","kickoff","tags","files","assignee","owner","start","due","estimate","progress","milestone","milestoneDate","dependsOn","priority","budget","spec","done"],"extra":[{"field":"kickoff","header":"Kick off","width":104,"fieldType":"button","fieldProps":{"label":"Start","color":"#2563eb"}},{"field":"milestoneDate","header":"Milestone date","width":160,"fieldType":"lookup","fieldProps":{"linkField":"milestone","field":"date"}},{"field":"dependsOn","header":"Depends on","width":200,"fieldType":"link","fieldProps":{"table":"tasks","multiple":true}}],"views":[{"id":"all","name":"All tasks","type":"grid","color":{"mode":"field","field":"status"},"state":{"sorting":[],"grouping":[],"columnWidths":{"task":230,"no":92,"status":130,"kickoff":104,"tags":190,"files":180,"assignee":160,"owner":170,"start":180,"due":200,"estimate":100,"progress":150,"milestone":130,"milestoneDate":160,"dependsOn":200,"priority":120,"budget":136,"spec":200,"done":80},"columnPinning":{"left":["task"],"right":[]},"columnOrder":["task","no","status","kickoff","tags","files","assignee","owner","start","due","estimate","progress","milestone","milestoneDate","dependsOn","priority","budget","spec","done"],"hiddenColumns":[],"globalFilter":"","columnFilters":{},"facetFilters":{}},"rowHeight":34},{"id":"board","name":"By status","type":"kanban","stackBy":"status"},{"id":"calendar","name":"Due dates","type":"calendar","dateField":"due","color":{"mode":"field","field":"status"}},{"id":"gallery","name":"Gallery","type":"gallery","coverField":"files"},{"id":"form","name":"Request a task","type":"form","formFields":["task","status","tags","assignee","due","priority","files"],"formDescription":"Adds a row to the tracker."}],"automations":[{"id":"overdue","name":"Overdue task","enabled":true,"trigger":{"type":"recordMatches"},"condition":{"kind":"fieldFilter","conjunction":"and","conditions":[{"column":"due","kind":"date","op":"isBefore","value":{"mode":"today"}},{"column":"status","kind":"select","op":"isNot","value":"Done"}]},"actions":[{"type":"highlight","fields":["due"],"background":"#fee2e2","color":"#b91c1c"},{"type":"notify","message":"{Task} is overdue: it was due {Due}","severity":"error"}]},{"id":"blocked","name":"Task blocked","enabled":true,"trigger":{"type":"recordMatches"},"condition":{"kind":"fieldFilter","conjunction":"and","conditions":[{"column":"status","kind":"select","op":"is","value":"Blocked"}]},"actions":[{"type":"notify","message":"{Task} is blocked ({Assignee})","severity":"warning"}]},{"id":"done","name":"Done closes the task","enabled":true,"trigger":{"type":"recordUpdated","fields":["status"]},"condition":{"kind":"fieldFilter","conjunction":"and","conditions":[{"column":"status","kind":"select","op":"is","value":"Done"}]},"actions":[{"type":"updateRecord","values":{"done":"true","progress":"100%"}},{"type":"notify","message":"{Task} is done","severity":"success"}]},{"id":"kickoff","name":"Start a task","enabled":true,"trigger":{"type":"button","field":"kickoff"},"actions":[{"type":"updateRecord","values":{"status":"In progress","start":"today"}}]},{"id":"request","name":"Triage a request","enabled":true,"trigger":{"type":"formSubmitted","view":"form"},"actions":[{"type":"updateRecord","values":{"status":"Todo","progress":"0%"}},{"type":"notify","message":"New request: {Task}"}]}]}';
comment on column "milestones"."name" is 'svgrid:{"field":"name","header":"Milestone","width":180,"fieldType":"text"}';
comment on column "milestones"."date" is 'svgrid:{"field":"date","header":"Date","width":180,"fieldType":"date","fieldProps":{"dateFormat":"friendly"}}';
comment on table "milestones" is 'svgrid:{"v":1,"name":"Milestones","position":1,"primaryField":"name","order":["name","date","tasks","progress","budget"],"extra":[{"field":"tasks","header":"Tasks","width":320,"fieldType":"link","fieldProps":{"table":"tasks","multiple":true,"inverse":"milestone"}},{"field":"progress","header":"Progress","width":130,"fieldType":"rollup","fieldProps":{"linkField":"tasks","field":"progress","aggregation":"AVERAGE"}},{"field":"budget","header":"Budget","width":130,"fieldType":"rollup","fieldProps":{"linkField":"tasks","field":"budget","aggregation":"SUM"}}],"views":[{"id":"milestones","name":"All milestones","type":"grid"}]}';
comment on table "tasks_depends_on" is 'svgrid:{"v":1,"junction":{"owner":"tasks","field":"dependsOn","from":"task_id","to":"depends_on_id"}}';

